// BAD: reading the counter here recomposes the whole Screen on every tick
@Composable
fun Screen(vm: VM) {
    val count by vm.count.collectAsStateWithLifecycle()
    Column {
        ExpensiveHeader()          // recomposes needlessly
        Text("Count: $count")
    }
}

// GOOD: push the read down so only the Text scope invalidates
@Composable
fun Screen(vm: VM) {
    Column {
        ExpensiveHeader()
        CounterText(count = { vm.count.value })   // lambda defers the read
    }
}

@Composable
fun CounterText(count: () -> Int) {
    Text("Count: ${count()}")   // only this scope restarts
}

// Unstable: List is an interface; a new list instance each emission breaks ===
data class FeedUiState(val items: List<Item>, val isRefreshing: Boolean)

// Stable: immutable collection + explicit contract
import kotlinx.collections.immutable.ImmutableList
import kotlinx.collections.immutable.persistentListOf

@Immutable
data class FeedUiState(
    val items: ImmutableList<Item> = persistentListOf(),
    val isRefreshing: Boolean = false
)

// Lazy lists: keys keep identity stable across reorders
LazyColumn {
    items(state.items, key = { it.id }, contentType = { it.kind }) { item ->
        ItemRow(item)
    }
}

