// Stateful wrapper — survives rotation
@Composable
fun SearchBarHost() {
    var query by rememberSaveable { mutableStateOf("") }
    SearchBar(query = query, onQueryChange = { query = it })
}

// Custom Saver for a non-Bundle-able type
data class Filter(val tag: String, val minScore: Int)

val FilterSaver = listSaver<Filter, Any>(
    save = { listOf(it.tag, it.minScore) },
    restore = { Filter(it[0] as String, it[1] as Int) }
)

var filter by rememberSaveable(stateSaver = ...) { mutableStateOf(Filter("all", 0)) }

@Composable
fun Screen(userId: String, onTimeout: () -> Unit, listState: LazyListState) {

    // restarts when userId changes — exactly the desired behaviour
    LaunchedEffect(userId) { viewModel.load(userId) }

    // long-lived effect that must see the LATEST callback without restarting
    val currentOnTimeout by rememberUpdatedState(onTimeout)
    LaunchedEffect(Unit) {
        delay(30_000)
        currentOnTimeout()
    }

    // needs teardown
    val lifecycleOwner = LocalLifecycleOwner.current
    DisposableEffect(lifecycleOwner) {
        val observer = LifecycleEventObserver { _, e -> if (e == ON_RESUME) viewModel.refresh() }
        lifecycleOwner.lifecycle.addObserver(observer)
        onDispose { lifecycleOwner.lifecycle.removeObserver(observer) }
    }

    // high-frequency -> low-frequency: only recomposes when the boolean flips
    val showFab by remember {
        derivedStateOf { listState.firstVisibleItemIndex > 0 }
    }

    // Compose state -> Flow, so you can debounce it
    LaunchedEffect(listState) {
        snapshotFlow { listState.firstVisibleItemIndex }
            .debounce(500)
            .collect { analytics.trackScroll(it) }
    }
}

// Reads scrollState during COMPOSITION -> recomposes every frame
@Composable
fun ParallaxHeaderSlow(scroll: ScrollState) {
    Image(
        painter = painter,
        contentDescription = null,
        modifier = Modifier.offset(y = (scroll.value * 0.5f).dp)
    )
}

// Reads it inside a LAYOUT lambda -> no recomposition at all
@Composable
fun ParallaxHeaderFast(scroll: ScrollState) {
    Image(
        painter = painter,
        contentDescription = null,
        modifier = Modifier.offset { IntOffset(x = 0, y = (scroll.value * 0.5f).toInt()) }
    )
}

@Serializable data object HomeKey : NavKey
@Serializable data class DetailKey(val itemId: String) : NavKey

@Composable
fun App() {
    val backStack = rememberNavBackStack(HomeKey)

    NavDisplay(
        backStack = backStack,
        onBack = { backStack.removeLastOrNull() },
        entryProvider = entryProvider {
            entry<HomeKey> {
                HomeScreen(onItemClick = { id -> backStack.add(DetailKey(id)) })
            }
            entry<DetailKey> { key ->
                DetailScreen(itemId = key.itemId)
            }
        }
    )
}
